; daa.asm -- chapter 9: DAA in all 2,048 cases
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "daa.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
TABLE   EQU $D000             ; A and F after DAA, two bytes a case
        ld hl, TABLE
        ld ix, before
nextf:  ld c, (ix+0)            ; C: F before DAA
        ld b, 0                 ; B: A before DAA, 0 to 255
nexta:  push bc
        pop af                  ; A = B, F = C
        daa
        push af
        pop de                  ; D = A after, E = F after
        ld (hl), d
        inc hl
        ld (hl), e
        inc hl
        inc b
        jr nz, nexta
        inc ix
        ld a, (ix+0)
        cp $FF                  ; the end of the list
        jr nz, nextf
stop:   jr stop
before: db $00, $01, $10, $11, $02, $03, $12, $13, $FF
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
